package com.example.macdeck

/**
 * Mirrors the Mac's `LockedPageProvider.lockedPage` exactly: same stable
 * page ID, same slot layout. Defined locally rather than received via
 * PAGE_SYNC because the Mac deliberately never includes this page in the
 * synced list (it's not one of the user's editable pages) — the phone
 * switches to it purely based on `LockStateChanged`.
 *
 * Slot layout (0-indexed), matching the Mac 1:1:
 *   0: Brightness down     1: Brightness up
 *   2: Volume down         3: Volume up
 *   4: KB brightness down  5: Play/Pause
 *   6: Unlock Mac
 *   7,8: (empty)
 *   9: KB brightness up
 */
object LockedPage {

    const val ID = "00000000-0000-0000-0000-000000000002"

    /** The slot the "Unlock Mac" tile sits in — gated behind biometric auth. */
    const val UNLOCK_SLOT_INDEX = 6

val kbBrightnessDownBase64 = ""
val kbBrightnessUpBase64 = ""
val brightnessUpBase64 = ""
val brightnessDownBase64 = ""
val unlockMacBase64 = ""
val volumeUpBase64 = ""
val volumeDownBase64 = ""
val playPauseBase64 = ""


    private fun controlTile(slot: Int, action: String, iconData: String? = null): DeckTile = DeckTile(
        id = "locked-slot-$slot",
        slotIndex = slot,
        tileType = SystemControlTile(action = action),
        iconData = iconData
    )

    val page: DeckPage = DeckPage(
        id = ID,
        name = "Locked",
        pageNumber = -1,
        tiles = listOf(
            controlTile(0, "brightnessDown", brightnessDownBase64),
            controlTile(1, "brightnessUp", brightnessUpBase64),
            controlTile(2, "volumeDown", volumeDownBase64),
            controlTile(3, "volumeUp", volumeUpBase64),
            controlTile(4, "kbBrightnessDown", kbBrightnessDownBase64),
            controlTile(5, "playPause", playPauseBase64),
            controlTile(6, "unlockMac", unlockMacBase64),
            null,
            null,
            controlTile(9, "kbBrightnessUp", kbBrightnessUpBase64)
        )
    )
}